/**
 * Console stream model: an append-only, bounded log buffer plus demo fixtures.
 *
 * The daemon RPC does not stream Renode/QMK console output yet. `ConsoleBuffer` keeps
 * memory bounded regardless of how many lines a future `telemetry.subscribe` RPC pushes.
 * Timestamps always come from the source line; the UI formats them but never invents them.
 */

export type ConsoleSource = "renode" | "qmk" | "renode-agent";
export type ConsoleLevel = "info" | "warn" | "error";

export interface ConsoleLine {
  id: string;
  /** ISO-8601 timestamp supplied by the producer; never generated by the UI. */
  at: string;
  source: ConsoleSource;
  level: ConsoleLevel;
  text: string;
}

/** Hard cap on retained lines; older lines are dropped first. Documented in the README. */
export const CONSOLE_BUFFER_LIMIT = 500;
/** How many of the retained lines the view renders at once. */
export const CONSOLE_VIEW_LIMIT = 200;

/**
 * Bounded FIFO buffer. `append` never grows past `limit`; `droppedCount` records how many
 * lines rolled off so the view can say so instead of silently hiding history.
 */
export class ConsoleBuffer {
  readonly limit: number;
  #lines: ConsoleLine[] = [];
  #dropped = 0;

  constructor(limit: number = CONSOLE_BUFFER_LIMIT) {
    if (!Number.isInteger(limit) || limit < 1) {
      throw new RangeError("Console buffer limit must be a positive integer.");
    }
    this.limit = limit;
  }

  append(line: ConsoleLine): void {
    this.#lines.push(line);
    while (this.#lines.length > this.limit) {
      this.#lines.shift();
      this.#dropped += 1;
    }
  }

  appendAll(lines: readonly ConsoleLine[]): void {
    for (const line of lines) this.append(line);
  }

  clear(): void {
    this.#lines = [];
    this.#dropped = 0;
  }

  get lines(): readonly ConsoleLine[] {
    return this.#lines;
  }

  get size(): number {
    return this.#lines.length;
  }

  get droppedCount(): number {
    return this.#dropped;
  }

  /** The most recent `limit` retained lines. */
  visible(limit: number = CONSOLE_VIEW_LIMIT): readonly ConsoleLine[] {
    if (limit >= this.#lines.length) return this.#lines;
    return this.#lines.slice(this.#lines.length - Math.max(1, limit));
  }
}

/** Renders a fixture/source timestamp as a stable UTC clock string. */
export function formatConsoleTimestamp(iso: string): string {
  const ms = Date.parse(iso);
  if (Number.isNaN(ms)) return iso;
  return `${new Date(ms).toISOString().slice(11, 23)}Z`;
}

const DEMO_BASE_MS = Date.parse("2026-11-04T10:41:38.000Z");

type DemoLineSpec = [offsetMs: number, source: ConsoleSource, level: ConsoleLevel, text: string];

const DEMO_SCRIPT: DemoLineSpec[] = [
  [0, "renode", "info", "Renode 1.17.0 · machine 'stm32f411' created from system_ir.json"],
  [12, "renode", "info", "Loading firmware.elf into flash at 0x08000000"],
  [41, "renode-agent", "info", "Attached debug UART on USART2 (PA2/PA3) at 115200 baud"],
  [96, "qmk", "info", "Compiled atomc/pad:default for STM32F411CEU6 (14 912 bytes)"],
  [140, "qmk", "info", "Matrix: 3 rows x 3 cols · DIODE_DIRECTION COL2ROW"],
  [180, "renode-agent", "info", "Scan cycle 1 · row B12 selected · cols A0..A2 sampled"],
  [212, "renode-agent", "info", "Scan cycle 2 · row B13 selected · cols A0..A2 sampled"],
  [244, "renode-agent", "info", "Scan cycle 3 · row B14 selected · cols A0..A2 sampled"],
  [279, "renode-agent", "info", "Key K0_0 down (row 0, col 0) · debounced 5 ms"],
  [338, "renode-agent", "info", "Key K0_0 up (row 0, col 0) · reported once"],
  [402, "qmk", "warn", "USB HID is not proven under Renode; matrix scan only"],
  [470, "renode", "info", "Simulation paused by the user"],
];

/** Deterministic demo console capture. Timestamps are fixture data, not wall-clock reads. */
export function createDemoConsoleLines(): ConsoleLine[] {
  return DEMO_SCRIPT.map(([offsetMs, source, level, text], index) => ({
    id: `console-${index}`,
    at: new Date(DEMO_BASE_MS + offsetMs).toISOString(),
    source,
    level,
    text,
  }));
}
